CREATE TABLE public."AutoPath" (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, event text NOT NULL, scouted_by uuid DEFAULT auth.uid() NOT NULL, team_number smallint NOT NULL, name text DEFAULT ''::text NOT NULL, alliance text NOT NULL, side text NOT NULL, path jsonb DEFAULT '[]'::jsonb NOT NULL);
ALTER TABLE public."AutoPath" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."AutoPath" ADD CONSTRAINT "AutoPath_pkey" PRIMARY KEY (id);
ALTER TABLE public."AutoPath" ADD CONSTRAINT "AutoPath_scouted_by_fkey" FOREIGN KEY (scouted_by) REFERENCES public."User"(user_id);
ALTER TABLE public."AutoPath" ADD CONSTRAINT "AutoPath_alliance_check" CHECK (alliance = ANY (ARRAY['red'::text, 'blue'::text]));
ALTER TABLE public."AutoPath" ADD CONSTRAINT "AutoPath_side_check" CHECK (side = ANY (ARRAY['left'::text, 'right'::text]));
GRANT ALL ON public."AutoPath" TO anon;
GRANT ALL ON public."AutoPath" TO authenticated;
GRANT ALL ON public."AutoPath" TO service_role;
CREATE POLICY "Enable insert for authenticated users only" ON public."AutoPath" FOR INSERT TO authenticated WITH CHECK ((scouted_by = auth.uid()));
CREATE POLICY "Enable read access for logged in users" ON public."AutoPath" FOR SELECT TO authenticated USING (true);
CREATE POLICY "Enable update for authenticated users only" ON public."AutoPath" FOR UPDATE TO authenticated USING (true);
CREATE POLICY "Enable delete for authenticated users only" ON public."AutoPath" FOR DELETE TO authenticated USING (true);
